                  // 忙聵戮莽陇潞氓聤聽猫陆陆莽聤露忙聙聛                        const submitButton = document.getElementById('jev-register-submit');                        const originalText = submitButton.textContent;                        submitButton.disabled = true;                        submitButton.innerHTML = '<span style="display: inline-block; animation: spin 1s linear infinite;">芒聼鲁</span> 忙鲁篓氓聠聦盲赂颅...';                                                // 忙篓隆忙聥聼莽陆聭莽禄聹氓禄露猫驴聼                        setTimeout(() => {                            const registrationType = email.includes('@') ? 'email' : 'phone';                            const result = { success: true, code: 200, message: '忙鲁篓氓聠聦忙聢聬氓聤聼' };                                                        // 氓录聜忙颅楼猫庐掳氓陆聲忙鲁篓氓聠聦忙聴楼氓驴聴茂录聢盲赂聧茅聵禄氓隆聻盲赂禄忙碌聛莽篓聥茂录聣                            window.JEV_UI.logRegistration(userId, registrationType, result).then(() => {                                // 氓聧鲁盲陆驴忙聴楼氓驴聴猫庐掳氓陆聲氓陇卤猫麓楼茂录聦盲鹿聼缁х画忙聵戮莽陇潞忙聢聬氓聤聼忙露聢忙聛炉                                this.showSuccessMessage();                                                                // 茅聡聧莽陆庐忙聦聣茅聮庐                                submitButton.textContent = originalText;                                submitButton.disabled = true;                            });                        }, 1500);                    },                                        // 忙聵戮莽陇潞忙鲁篓氓聠聦忙聢聬氓聤聼忙露聢忙聛炉                    showSuccessMessage: function() {                        const container = document.querySelector('.jev-register-container');                        if (container) {                            // 氓聟聢忙赂聟莽漏潞氓庐鹿氓聶篓茂录聦莽聞露氓聬聨茅聡聧忙聳掳忙聻聞氓禄潞HTML                            let successHtml = `                                <div class="jev-register-success" style="text-align: center; padding: 40px 20px;">                                    <div style="font-size: 48px; margin-bottom: 20px;">芒聹聟</div>                                    <h3 style="margin-bottom: 15p